extension DailyVerses {
    /// One verse for each day of the year, in the order the list gives them.
    public static let all: [Verse] = [
        Verse(text: "And whatever you do, in word or deed, do it all in the name of the Lord Jesus, giving thanks to God the Father through Him.", reference: "Colossians 3:17"),
        Verse(text: "“Be still and know that I am God; I will be exalted among the nations, I will be exalted over the earth.”", reference: "Psalm 46:10"),
        Verse(text: "The LORD is good, a stronghold in the day of distress; He cares for those who trust in Him.", reference: "Nahum 1:7"),
        Verse(text: "Then Jesus said to all of them, “If anyone wants to come after Me, he must deny himself and take up his cross daily and follow Me.”", reference: "Luke 9:23"),
        Verse(text: "So God created man in His own image; in the image of God He created him; male and female He created them.", reference: "Genesis 1:27"),
        Verse(text: "A good name is more desirable than great riches; favor is better than silver and gold.", reference: "Proverbs 22:1"),
        Verse(text: "But now, this is what the LORD says—He who created you, O Jacob, and He who formed you, O Israel: “Do not fear, for I have redeemed you; I have called you by your name; you are Mine!”", reference: "Isaiah 43:1"),
        Verse(text: "Be still before the LORD and wait patiently for Him; do not fret when men prosper in their ways, when they carry out wicked schemes.", reference: "Psalm 37:7"),
        Verse(text: "Submit yourselves, then, to God. Resist the devil, and he will flee from you.", reference: "James 4:7"),
        Verse(text: "And we have come to know and believe the love that God has for us. God is love; whoever abides in love abides in God, and God in him.", reference: "1 John 4:16"),
        Verse(text: "“Worthy are You, our Lord and God, to receive glory and honor and power, for You created all things; by Your will they exist and were created.”", reference: "Revelation 4:11"),
        Verse(text: "Peace I leave with you; My peace I give to you. I do not give to you as the world gives. Do not let your hearts be troubled; do not be afraid.", reference: "John 14:27"),
        Verse(text: "Ask, and it will be given to you; seek, and you will find; knock, and the door will be opened to you.", reference: "Matthew 7:7"),
        Verse(text: "Therefore do not worry about tomorrow, for tomorrow will worry about itself. Today has enough trouble of its own.", reference: "Matthew 6:34"),
        Verse(text: "The LORD is a refuge for the oppressed, a stronghold in times of trouble. Those who know Your name trust in You, for You, O LORD, have not forsaken those who seek You.", reference: "Psalm 9:9–10"),
        Verse(text: "Humble yourselves before the Lord, and He will exalt you.", reference: "James 4:10"),
        Verse(text: "The LORD is my shepherd; I shall not want.", reference: "Psalm 23:1"),
        Verse(text: "In the morning, O LORD, You hear my voice; at daybreak I lay my plea before You and wait in expectation.", reference: "Psalm 5:3"),
        Verse(text: "You will seek Me and find Me when you search for Me with all your heart.", reference: "Jeremiah 29:13"),
        Verse(text: "Trust in the LORD forever, because GOD the LORD is the Rock eternal.", reference: "Isaiah 26:4"),
        Verse(text: "The LORD gives His people strength; the LORD blesses His people with peace.", reference: "Psalm 29:11"),
        Verse(text: "The One who calls you is faithful, and He will do it.", reference: "1 Thessalonians 5:24"),
        Verse(text: "My help comes from the LORD, the Maker of heaven and earth.", reference: "Psalm 121:2"),
        Verse(text: "And we know that God works all things together for the good of those who love Him, who are called according to His purpose.", reference: "Romans 8:28"),
        Verse(text: "Let the peace of Christ rule in your hearts, for to this you were called as members of one body. And be thankful.", reference: "Colossians 3:15"),
        Verse(text: "Once again, Jesus spoke to the people and said, “I am the light of the world. Whoever follows Me will never walk in the darkness, but will have the light of life.”", reference: "John 8:12"),
        Verse(text: "More than that, I count all things as loss compared to the surpassing excellence of knowing Christ Jesus my Lord, for whom I have lost all things. I consider them rubbish, that I may gain Christ", reference: "Philippians 3:8"),
        Verse(text: "Jesus looked at them and said, “With man this is impossible, but with God all things are possible.”", reference: "Matthew 19:26"),
        Verse(text: "Blessed are those who hunger and thirst for righteousness, for they will be filled.", reference: "Matthew 5:6"),
        Verse(text: "Now to Him who is able to do immeasurably more than all we ask or imagine, according to His power that is at work within us, to Him be the glory in the church and in Christ Jesus throughout all generations, forever and ever. Amen.", reference: "Ephesians 3:20–21"),
        Verse(text: "Do nothing out of selfish ambition or empty pride, but in humility consider others more important than yourselves.", reference: "Philippians 2:3"),
        Verse(text: "I am the Alpha and the Omega, the First and the Last, the Beginning and the End.", reference: "Revelation 22:13"),
        Verse(text: "Hatred stirs up dissension, but love covers all transgressions.", reference: "Proverbs 10:12"),
        Verse(text: "Create in me a clean heart, O God, and renew a right spirit within me.", reference: "Psalm 51:10"),
        Verse(text: "I delight to do Your will, O my God; Your law is within my heart.", reference: "Psalm 40:8"),
        Verse(text: "To the Lord our God belong compassion and forgiveness, even though we have rebelled against Him", reference: "Daniel 9:9"),
        Verse(text: "The LORD will guard you from all evil; He will preserve your soul. The LORD will watch over your coming and going, both now and forevermore.", reference: "Psalm 121:7–8"),
        Verse(text: "You have made known to me the path of life; You will fill me with joy in Your presence, with eternal pleasures at Your right hand.", reference: "Psalm 16:11"),
        Verse(text: "What then shall we say in response to these things? If God is for us, who can be against us?", reference: "Romans 8:31"),
        Verse(text: "Therefore, just as you have received Christ Jesus as Lord, continue to walk in Him, rooted and built up in Him, established in the faith as you were taught, and overflowing with thankfulness.", reference: "Colossians 2:6–7"),
        Verse(text: "The grass withers and the flowers fall, but the word of our God stands forever.", reference: "Isaiah 40:8"),
        Verse(text: "But blessed is the man who trusts in the LORD, whose confidence is in Him.", reference: "Jeremiah 17:7"),
        Verse(text: "For we are God’s workmanship, created in Christ Jesus to do good works, which God prepared in advance as our way of life.", reference: "Ephesians 2:10"),
        Verse(text: "Cast all your anxiety on Him, because He cares for you.", reference: "1 Peter 5:7"),
        Verse(text: "So we fix our eyes not on what is seen, but on what is unseen. For what is seen is temporary, but what is unseen is eternal.", reference: "2 Corinthians 4:18"),
        Verse(text: "For the LORD God is a sun and a shield; the LORD gives grace and glory; He withholds no good thing from those who walk with integrity.", reference: "Psalm 84:11"),
        Verse(text: "Therefore the LORD longs to be gracious to you; therefore He rises to show you compassion, for the LORD is a just God. Blessed are all who wait for Him.", reference: "Isaiah 30:18"),
        Verse(text: "When I am afraid, I put my trust in You.", reference: "Psalm 56:3"),
        Verse(text: "I will lie down and sleep in peace, for You alone, O LORD, make me dwell in safety.", reference: "Psalm 4:8"),
        Verse(text: "The Law of the LORD is perfect, reviving the soul; the testimony of the LORD is trustworthy, making wise the simple.", reference: "Psalm 19:7"),
        Verse(text: "But to all who did receive Him, to those who believed in His name, He gave the right to become children of God…", reference: "John 1:12"),
        Verse(text: "Whoever does not love does not know God, because God is love.", reference: "1 John 4:8"),
        Verse(text: "And after you have suffered for a little while, the God of all grace, who has called you to His eternal glory in Christ, will Himself restore you, secure you, strengthen you, and establish you.", reference: "1 Peter 5:10"),
        Verse(text: "Guard your heart with all diligence, for from it flow springs of life.", reference: "Proverbs 4:23"),
        Verse(text: "Greater love has no one than this, that he lay down his life for his friends.", reference: "John 15:13"),
        Verse(text: "Blessed be the God and Father of our Lord Jesus Christ, the Father of compassion and the God of all comfort, who comforts us in all our troubles, so that we can comfort those in any trouble with the comfort we ourselves have received from God.", reference: "2 Corinthians 1:3–4"),
        Verse(text: "Therefore I tell you, whatever you ask for in prayer, believe that you have received it, and it will be yours.", reference: "Mark 11:24"),
        Verse(text: "Be strong and courageous, all you who hope in the LORD.", reference: "Psalm 31:24"),
        Verse(text: "But seek first the kingdom of God and His righteousness, and all these things will be added unto you.", reference: "Matthew 6:33"),
        Verse(text: "In the beginning was the Word, and the Word was with God, and the Word was God.", reference: "John 1:1"),
        Verse(text: "But grow in the grace and knowledge of our Lord and Savior Jesus Christ. To Him be the glory both now and to the day of eternity. Amen.", reference: "2 Peter 3:18"),
        Verse(text: "For Your loving devotion reaches to the heavens, and Your faithfulness to the clouds.", reference: "Psalm 57:10"),
        Verse(text: "‘He will wipe away every tear from their eyes,’ and there will be no more death or mourning or crying or pain, for the former things have passed away.", reference: "Revelation 21:4"),
        Verse(text: "So let us know—let us press on to know the LORD. As surely as the sun rises, He will appear; He will come to us like the rain, like the spring showers that water the earth.", reference: "Hosea 6:3"),
        Verse(text: "“Do not call to mind the former things; pay no attention to the things of old. Behold, I am about to do something new; even now it is coming. Do you not see it? Indeed, I will make a way in the wilderness and streams in the desert.”", reference: "Isaiah 43:18–19"),
        Verse(text: "For the word of God is living and active. Sharper than any double-edged sword, it pierces even to dividing soul and spirit, joints and marrow. It judges the thoughts and intentions of the heart.", reference: "Hebrews 4:12"),
        Verse(text: "Draw near to God, and He will draw near to you. Cleanse your hands, you sinners, and purify your hearts, you double-minded.", reference: "James 4:8"),
        Verse(text: "I am not saying this out of need, for I have learned to be content regardless of my circumstances.", reference: "Philippians 4:11"),
        Verse(text: "Commit your way to the LORD; trust in Him, and He will do it.", reference: "Psalm 37:5"),
        Verse(text: "The LORD is my light and my salvation—whom shall I fear? The LORD is the stronghold of my life—whom shall I dread?", reference: "Psalm 27:1"),
        Verse(text: "Be joyful in hope, patient in affliction, persistent in prayer.", reference: "Romans 12:12"),
        Verse(text: "The LORD your God is among you; He is mighty to save. He will rejoice over you with gladness; He will quiet you with His love; He will rejoice over you with singing.", reference: "Zephaniah 3:17"),
        Verse(text: "The earth is the LORD’s, and the fullness thereof, the world and all who dwell therein.", reference: "Psalm 24:1"),
        Verse(text: "The eternal God is your dwelling place, and underneath are the everlasting arms. He drives out the enemy before you, giving the command, ‘Destroy him!’", reference: "Deuteronomy 33:27"),
        Verse(text: "Whom have I in heaven but You? And on earth I desire no one besides You.", reference: "Psalm 73:25"),
        Verse(text: "For God so loved the world that He gave His one and only Son, that everyone who believes in Him shall not perish but have eternal life.", reference: "John 3:16"),
        Verse(text: "Now the Lord is the Spirit, and where the Spirit of the Lord is, there is freedom.", reference: "2 Corinthians 3:17"),
        Verse(text: "For I am the LORD your God, who takes hold of your right hand and tells you: Do not fear, I will help you.", reference: "Isaiah 41:13"),
        Verse(text: "His divine power has given us everything we need for life and godliness through the knowledge of Him who called us by His own glory and excellence.", reference: "2 Peter 1:3"),
        Verse(text: "But when you pray, go into your inner room, shut your door, and pray to your Father, who is unseen. And your Father, who sees what is done in secret, will reward you.", reference: "Matthew 6:6"),
        Verse(text: "The LORD is my strength and my shield; my heart trusts in Him, and I am helped. Therefore my heart rejoices, and I give thanks to Him with my song.", reference: "Psalm 28:7"),
        Verse(text: "Blessed be the God and Father of our Lord Jesus Christ! By His great mercy He has given us new birth into a living hope through the resurrection of Jesus Christ from the dead…", reference: "1 Peter 1:3"),
        Verse(text: "Our soul waits for the LORD; He is our help and our shield. For our hearts rejoice in Him, since we trust in His holy name.", reference: "Psalm 33:20–21"),
        Verse(text: "For the message of the cross is foolishness to those who are perishing, but to us who are being saved it is the power of God.", reference: "1 Corinthians 1:18"),
        Verse(text: "What does it profit a man to gain the whole world, yet forfeit his soul?", reference: "Mark 8:36"),
        Verse(text: "Great is our Lord, and mighty in power; His understanding has no limit.", reference: "Psalm 147:5"),
        Verse(text: "So teach us to number our days, that we may present a heart of wisdom.", reference: "Psalm 90:12"),
        Verse(text: "Though you have not seen Him, you love Him; and though you do not see Him now, you believe in Him and rejoice with an inexpressible and glorious joy…", reference: "1 Peter 1:8"),
        Verse(text: "I wait for the LORD; my soul does wait, and in His word I put my hope.", reference: "Psalm 130:5"),
        Verse(text: "Surely God is my salvation; I will trust and not be afraid. For the LORD GOD is my strength and my song, and He also has become my salvation.", reference: "Isaiah 12:2"),
        Verse(text: "A man’s heart plans his course, but the LORD determines his steps.", reference: "Proverbs 16:9"),
        Verse(text: "Because Your loving devotion is better than life, my lips will glorify You.", reference: "Psalm 63:3"),
        Verse(text: "Let no one despise your youth, but set an example for the believers in speech, in conduct, in love, in faith, in purity.", reference: "1 Timothy 4:12"),
        Verse(text: "The Lord is not slow in keeping His promise as some understand slowness, but is patient with you, not wanting anyone to perish but everyone to come to repentance.", reference: "2 Peter 3:9"),
        Verse(text: "Let this mind be in you which was also in Christ Jesus…", reference: "Philippians 2:5"),
        Verse(text: "Keep your lives free from the love of money and be content with what you have, for God has said: “Never will I leave you, never will I forsake you.”", reference: "Hebrews 13:5"),
        Verse(text: "The fear of man is a snare, but whoever trusts in the LORD is set securely on high.", reference: "Proverbs 29:25"),
        Verse(text: "For the LORD is good, and His loving devotion endures forever; His faithfulness continues to all generations.", reference: "Psalm 100:5"),
        Verse(text: "I have fought the good fight, I have finished the race, I have kept the faith.", reference: "2 Timothy 4:7"),
        Verse(text: "Even to your old age, I will be the same, and I will bear you up when you turn gray. I have made you, and I will carry you; I will sustain you and deliver you.", reference: "Isaiah 46:4"),
        Verse(text: "The thief comes only to steal and kill and destroy. I have come that they may have life, and have it in all its fullness.", reference: "John 10:10"),
        Verse(text: "And God is able to make all grace abound to you, so that in all things, at all times, having all that you need, you will abound in every good work.", reference: "2 Corinthians 9:8"),
        Verse(text: "What will it profit a man if he gains the whole world, yet forfeits his soul? Or what can a man give in exchange for his soul?", reference: "Matthew 16:26"),
        Verse(text: "This is my comfort in affliction, that Your promise has given me life.", reference: "Psalm 119:50"),
        Verse(text: "Do to others as you would have them do to you.", reference: "Luke 6:31"),
        Verse(text: "So if the Son sets you free, you will be free indeed.", reference: "John 8:36"),
        Verse(text: "Great is the LORD and greatly to be praised; His greatness is unsearchable.", reference: "Psalm 145:3"),
        Verse(text: "For even the Son of Man did not come to be served, but to serve, and to give His life as a ransom for many.", reference: "Mark 10:45"),
        Verse(text: "But you are a chosen people, a royal priesthood, a holy nation, a people for God’s own possession, to proclaim the virtues of Him who called you out of darkness into His marvelous light.", reference: "1 Peter 2:9"),
        Verse(text: "But He said to me, “My grace is sufficient for you, for My power is perfected in weakness.” Therefore I will boast all the more gladly in my weaknesses, so that the power of Christ may rest on me.", reference: "2 Corinthians 12:9"),
        Verse(text: "Jesus declared, “‘Love the Lord your God with all your heart and with all your soul and with all your mind.’ This is the first and greatest commandment. And the second is like it: ‘Love your neighbor as yourself.’”", reference: "Matthew 22:37–39"),
        Verse(text: "“For My thoughts are not your thoughts, neither are your ways My ways,” declares the LORD. “For as the heavens are higher than the earth, so My ways are higher than your ways and My thoughts than your thoughts.”", reference: "Isaiah 55:8–9"),
        Verse(text: "For our light and momentary affliction is producing for us an eternal weight of glory that is far beyond comparison.", reference: "2 Corinthians 4:17"),
        Verse(text: "The LORD is good to those who wait for Him, to the soul who seeks Him.", reference: "Lamentations 3:25"),
        Verse(text: "Give thanks to the LORD, for He is good; His loving devotion endures forever.", reference: "Psalm 118:29"),
        Verse(text: "But You, O LORD, are a shield around me, my glory, and the One who lifts my head.", reference: "Psalm 3:3"),
        Verse(text: "For we do not have a high priest who is unable to sympathize with our weaknesses, but we have one who was tempted in every way that we are, yet was without sin.", reference: "Hebrews 4:15"),
        Verse(text: "Do not boast about tomorrow, for you do not know what a day may bring.", reference: "Proverbs 27:1"),
        Verse(text: "I have told you these things so that in Me you may have peace. In the world you will have tribulation. But take courage; I have overcome the world!", reference: "John 16:33"),
        Verse(text: "Commit your works to the LORD and your plans will be achieved.", reference: "Proverbs 16:3"),
        Verse(text: "I have hidden Your word in my heart that I might not sin against You.", reference: "Psalm 119:11"),
        Verse(text: "The LORD is my rock, my fortress, and my deliverer. My God is my rock, in whom I take refuge, my shield, and the horn of my salvation, my stronghold.", reference: "Psalm 18:2"),
        Verse(text: "Because everyone born of God overcomes the world. And this is the victory that has overcome the world: our faith.", reference: "1 John 5:4"),
        Verse(text: "Anxiety weighs down the heart of a man, but a good word cheers it up.", reference: "Proverbs 12:25"),
        Verse(text: "Do you not know that your body is a temple of the Holy Spirit who is in you, whom you have received from God? You are not your own; you were bought at a price. Therefore glorify God with your body.", reference: "1 Corinthians 6:19–20"),
        Verse(text: "Now to Him who is able to keep you from stumbling and to present you unblemished in His glorious presence, with great joy— to the only God our Savior be glory, majesty, dominion, and authority through Jesus Christ our Lord before all time, and now, and for all eternity. Amen.", reference: "Jude 1:24–25"),
        Verse(text: "Brothers, I do not consider myself yet to have taken hold of it. But one thing I do: Forgetting what is behind and straining toward what is ahead, I press on toward the goal to win the prize of God’s heavenly calling in Christ Jesus.", reference: "Philippians 3:13–14"),
        Verse(text: "“Oh, Lord GOD! You have made the heavens and the earth by Your great power and outstretched arm. Nothing is too difficult for You!”", reference: "Jeremiah 32:17"),
        Verse(text: "Look, I am with you, and I will watch over you wherever you go, and I will bring you back to this land. For I will not leave you until I have done what I have promised you.", reference: "Genesis 28:15"),
        Verse(text: "Sing to the LORD a new song; sing to the LORD, all the earth. Sing to the LORD, bless His name; proclaim His salvation day after day.", reference: "Psalm 96:1–2"),
        Verse(text: "Therefore, my beloved brothers, be steadfast and immovable. Always excel in the work of the Lord, because you know that your labor in the Lord is not in vain.", reference: "1 Corinthians 15:58"),
        Verse(text: "Every word of God is flawless; He is a shield to those who take refuge in Him.", reference: "Proverbs 30:5"),
        Verse(text: "Let the word of Christ richly dwell within you as you teach and admonish one another with all wisdom, and as you sing psalms, hymns, and spiritual songs with gratitude in your hearts to God.", reference: "Colossians 3:16"),
        Verse(text: "Remember what happened long ago, for I am God, and there is no other; I am God, and there is none like Me. I declare the end from the beginning, and from ancient times what is still to come. I say, ‘My purpose will stand, and all My good pleasure I will accomplish.’", reference: "Isaiah 46:9–10"),
        Verse(text: "Your word is a lamp to my feet and a light to my path.", reference: "Psalm 119:105"),
        Verse(text: "Be not wise in your own eyes; fear the LORD and turn away from evil.", reference: "Proverbs 3:7"),
        Verse(text: "If we confess our sins, He is faithful and just to forgive us our sins and to cleanse us from all unrighteousness.", reference: "1 John 1:9"),
        Verse(text: "When you pass through the waters, I will be with you; and when you go through the rivers, they will not overwhelm you. When you walk through the fire, you will not be scorched; the flames will not set you ablaze.", reference: "Isaiah 43:2"),
        Verse(text: "The LORD is near to all who call on Him, to all who call out to Him in truth.", reference: "Psalm 145:18"),
        Verse(text: "Therefore we do not lose heart. Though our outer self is wasting away, yet our inner self is being renewed day by day.", reference: "2 Corinthians 4:16"),
        Verse(text: "I will give thanks to the LORD with all my heart; I will recount all Your wonders.", reference: "Psalm 9:1"),
        Verse(text: "We love because He first loved us.", reference: "1 John 4:19"),
        Verse(text: "Not to us, O LORD, not to us, but to Your name be the glory, because of Your loving devotion, because of Your faithfulness.", reference: "Psalm 115:1"),
        Verse(text: "In Him we have redemption through His blood, the forgiveness of our trespasses, according to the riches of His grace", reference: "Ephesians 1:7"),
        Verse(text: "For where your treasure is, there your heart will be also.", reference: "Luke 12:34"),
        Verse(text: "Consider it pure joy, my brothers, when you encounter trials of many kinds, because you know that the testing of your faith develops perseverance.", reference: "James 1:2–3"),
        Verse(text: "So I tell you: Ask, and it will be given to you; seek, and you will find; knock, and the door will be opened to you.", reference: "Luke 11:9"),
        Verse(text: "And love consists in this: not that we loved God, but that He loved us and sent His Son as the atoning sacrifice for our sins.", reference: "1 John 4:10"),
        Verse(text: "“The LORD is my portion,” says my soul, “therefore I will hope in Him.”", reference: "Lamentations 3:24"),
        Verse(text: "So rend your hearts and not your garments, and return to the LORD your God. For He is gracious and compassionate, slow to anger, abounding in loving devotion. And He relents from sending disaster.", reference: "Joel 2:13"),
        Verse(text: "I am the vine and you are the branches. The one who remains in Me, and I in him, will bear much fruit. For apart from Me you can do nothing.", reference: "John 15:5"),
        Verse(text: "Teach me Your way, O LORD, that I may walk in Your truth. Give me an undivided heart, that I may fear Your name.", reference: "Psalm 86:11"),
        Verse(text: "Jesus said to him, “Because you have seen Me, you have believed; blessed are those who have not seen and yet have believed.”", reference: "John 20:29"),
        Verse(text: "Little children, let us love not in word and speech, but in action and truth.", reference: "1 John 3:18"),
        Verse(text: "Though the fig tree does not bud and no fruit is on the vines, though the olive crop fails and the fields produce no food, though the sheep are cut off from the fold and no cattle are in the stalls, yet I will exult in the LORD; I will rejoice in the God of my salvation!", reference: "Habakkuk 3:17–18"),
        Verse(text: "For God has not given us a spirit of fear, but of power, love, and self-control.", reference: "2 Timothy 1:7"),
        Verse(text: "Let us not grow weary in well-doing, for in due time we will reap a harvest if we do not give up.", reference: "Galatians 6:9"),
        Verse(text: "Finally, be strong in the Lord and in His mighty power.", reference: "Ephesians 6:10"),
        Verse(text: "God is Spirit, and His worshipers must worship Him in spirit and in truth.", reference: "John 4:24"),
        Verse(text: "Be imitators of God, therefore, as beloved children, and walk in love, just as Christ loved us and gave Himself up for us as a fragrant sacrificial offering to God.", reference: "Ephesians 5:1–2"),
        Verse(text: "Give thanks to the LORD, for He is good; His loving devotion endures forever.", reference: "Psalm 107:1"),
        Verse(text: "He who testifies to these things says, “Yes, I am coming soon.” Amen. Come, Lord Jesus!", reference: "Revelation 22:20"),
        Verse(text: "Blessed be God, who has not rejected my prayer or withheld from me His loving devotion!", reference: "Psalm 66:20"),
        Verse(text: "As a father has compassion on his children, so the LORD has compassion on those who fear Him.", reference: "Psalm 103:13"),
        Verse(text: "Give thanks to the LORD, for He is good; His loving devotion endures forever.", reference: "1 Chronicles 16:34"),
        Verse(text: "Come to Me, all you who are weary and burdened, and I will give you rest.", reference: "Matthew 11:28"),
        Verse(text: "He gives power to the faint and increases the strength of the weak.", reference: "Isaiah 40:29"),
        Verse(text: "Restore to me the joy of Your salvation, and sustain me with a willing spirit.", reference: "Psalm 51:12"),
        Verse(text: "Behold, I stand at the door and knock. If anyone hears My voice and opens the door, I will come in and dine with him, and he with Me.", reference: "Revelation 3:20"),
        Verse(text: "And the LORD answered, “My Presence will go with you, and I will give you rest.”", reference: "Exodus 33:14"),
        Verse(text: "Now may the Lord of peace Himself give you peace at all times and in every way. The Lord be with all of you.", reference: "2 Thessalonians 3:16"),
        Verse(text: "Truly, truly, I tell you, whoever hears My word and believes Him who sent Me has eternal life and will not come under judgment. Indeed, he has crossed over from death to life.", reference: "John 5:24"),
        Verse(text: "May the words of my mouth and the meditation of my heart be pleasing in Your sight, O LORD, my Rock and my Redeemer.", reference: "Psalm 19:14"),
        Verse(text: "But He was pierced for our transgressions, He was crushed for our iniquities; the punishment that brought us peace was upon Him, and by His stripes we are healed.", reference: "Isaiah 53:5"),
